const targetAccounts = [
  { username: 'chroniki_claude', userId: 'THREADS_USER_ID_1', description: 'Claude Code専門家' },
  { username: 'ai_trend_jp', userId: 'THREADS_USER_ID_2', description: 'AIトレンド情報' },
  { username: 'prompt_engineering_jp', userId: 'THREADS_USER_ID_3', description: 'プロンプトエンジニアリング' }
];
const threeHoursAgo = Math.floor((Date.now() - 3 * 60 * 60 * 1000) / 1000);
return targetAccounts.map(acc => ({ json: { username: acc.username, userId: acc.userId, description: acc.description, since: threeHoursAgo } }));

const posts = $json.data || [];
if (posts.length === 0) return [{ json: { skip: true } }];
const aiKeywords = ['AI', 'Claude', 'GPT', 'ChatGPT', 'Gemini', '人工知能', '機械学習', 'プロンプト', 'LLM', '生成AI'];
const aiPosts = posts.filter(post => aiKeywords.some(kw => (post.text || '').toLowerCase().includes(kw.toLowerCase())));
if (aiPosts.length === 0) return [{ json: { skip: true } }];
const username = $('対象アカウント設定').item.json.username;
const postsText = aiPosts.map(p => `- ${p.text} (${p.permalink})`).join('\n');
return [{ json: { username, postCount: aiPosts.length, postsText, posts: aiPosts } }];

const GITHUB_TOKEN = $env.GITHUB_TOKEN || '';
const BASE = 'https://api.github.com/repos/liquitex-coder/ai-solution-/contents/n8n/prompts/';
const headers = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'n8n-ai-navi/1.0' };
if (GITHUB_TOKEN) headers['Authorization'] = `token ${GITHUB_TOKEN}`;
async function fetchPrompt(file) {
  try {
    const res = await fetch(BASE + file, { headers });
    if (!res.ok) return '';
    const data = await res.json();
    return Buffer.from((data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
  } catch(e) { return ''; }
}
const [copyright, wfPrompt] = await Promise.all([
  fetchPrompt('00-copyright-transform.md'),
  fetchPrompt('04-threads-influencer.md')
]);
return [{ json: { ...$json, promptContent: copyright + '\n\n---\n\n' + wfPrompt } }];

const content = $json.content[0].text;
const threadsData = $('AI関連投稿をフィルタリング').item.json;
const firstPermalink = (threadsData.posts && threadsData.posts[0]) ? (threadsData.posts[0].permalink || '') : '';
return [{ json: { title: `【Threads】@${threadsData.username}のAIノウハウまとめ（${threadsData.postCount}件）`, content, wp_status: 'draft', source_url: firstPermalink } }];

// Auditor Gate — graceful degrade (INV-R2: LLM-free verdict)
const auditorUrl = $env.CLAIM_AUDITOR_URL || '';
const content = $json.content || '';
const sourceUrl = $json.source_url || '';
if (!auditorUrl) {
  return [{ json: { ...$json, verdict: 'SKIP', wp_status: 'draft',
    audit_note: 'CLAIM_AUDITOR_URL未設定 → 下書き保存' } }];
}
try {
  const res = await fetch(`${auditorUrl}/audit`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      content,
      source_urls: sourceUrl ? [sourceUrl] : [],
      skill_ref: '04-threads-influencer'
    })
  });
  if (!res.ok) {
    return [{ json: { ...$json, verdict: 'UNVERIFIABLE', wp_status: 'draft',
      audit_note: `Auditor HTTP ${res.status}` } }];
  }
  const result = await res.json();
  return [{ json: { ...$json, ...result,
    wp_status: result.verdict === 'PASS' ? 'publish' : 'draft' } }];
} catch(e) {
  return [{ json: { ...$json, verdict: 'UNVERIFIABLE', wp_status: 'draft',
    audit_note: e.message } }];
}
